/**
 * Lazy loading of the full French lemma list (lexicon-full-data.ts, generated by scripts/fr-build-lexicon.mts from the kaikki.org
 * extract; about 1 MB of text, 78,000 entries; lemma + part of speech + a noun's gender + three flags, NO meanings; docs/french/LEXICON.md).
 * The data module is NOT imported statically: `loadFrenchLexicon()` fetches it with a dynamic import (the bundler makes it a chunk of its own),
 * parses it ONCE into one Map (normalized lemma → a small integer bit mask), shares a load in flight, and resets on failure so a retry can succeed.
 * Before the load every lookup answers false / undefined. Modelled on latin/lexicon-load.ts.
 *
 * The mask (31 bits): bits 0-5 the part of speech is listed (NOUN, VERB, ADJ, ADV, PROPN, INTJ); bits 6-7 the gender (1 m, 2 f, 3 both);
 * bits 8-13 dated per part of speech; bits 14-19 aspirated h per part of speech; bit 20 pronominal-only verb.
 */
import type { PartOfSpeech } from '../../core';
import { normalizeFr } from './orth';

export const FR_FULL_SOURCE_ID = 'kaikki-fr@2026-10-30';

const POS_LIST = ['NOUN', 'VERB', 'ADJ', 'ADV', 'PROPN', 'INTJ'] as const;
const POS_BIT: Readonly<Record<string, number>> = { NOUN: 0, VERB: 1, ADJ: 2, ADV: 3, PROPN: 4, INTJ: 5 };
const GENDER_SHIFT = 6, DATED_SHIFT = 8, H_SHIFT = 14, PRON_BIT = 20;
const GENDER_NAME = [undefined, 'Masc', 'Fem', 'Fem,Masc'] as const;

let map: Map<string, number> | undefined;
let pending: Promise<void> | undefined;
let parseCount = 0;
const waiting: Array<() => void> = [];

function parse(data: Readonly<Record<string, string>>): Map<string, number> {
  parseCount++;
  const m = new Map<string, number>();
  for (let p = 0; p < POS_LIST.length; p++) {
    const pos = POS_LIST[p];
    const text = data[pos] ?? '';
    let i = 0;
    const n = text.length;
    while (i < n) {
      let j = text.indexOf('\n', i);
      if (j < 0) j = n;
      let lemmaEnd = j, g = 0, flags = 0;
      // entry = lemma [/g] [!flags]; a lemma holds neither '/' nor '!' (the build leaves such entries out)
      // flags are at most three letters after the '!', the gender two characters '/g': only the entry's last few characters are looked at
      for (let k = j - 1; k >= i && k >= j - 4; k--) {
        if (text.charCodeAt(k) === 33) {
          lemmaEnd = k;
          for (let q = k + 1; q < j; q++) { const c = text.charCodeAt(q); flags |= c === 112 ? 1 : c === 111 ? 2 : c === 104 ? 4 : 0; }
          break;
        }
      }
      if (lemmaEnd - 2 >= i && text.charCodeAt(lemmaEnd - 2) === 47) {
        const c = text.charCodeAt(lemmaEnd - 1);
        g = c === 109 ? 1 : c === 102 ? 2 : 3;
        lemmaEnd -= 2;
      }
      const raw = text.slice(i, lemmaEnd);
      i = j + 1;
      const key = normalizeFr(raw);
      let mask = (m.get(key) ?? 0) | (1 << POS_BIT[pos]);
      if (p === 0) mask |= g << GENDER_SHIFT; // gender is a noun's: OR keeps m|f = both when two spellings fold together
      if (flags & 2) mask |= 1 << (DATED_SHIFT + p);
      if (flags & 4) mask |= 1 << (H_SHIFT + p);
      if (flags & 1) mask |= 1 << PRON_BIT;
      m.set(key, mask);
    }
  }
  return m;
}

/** Fetches and parses the list. Idempotent; a load in flight is shared; a failed load can be retried. */
export function loadFrenchLexicon(): Promise<void> {
  if (map) return Promise.resolve();
  pending ??= import('./lexicon-full-data').then((mod) => {
    map = parse(mod.FR_FULL);
    pending = undefined;
    for (const cb of waiting.splice(0)) cb();
  }).catch((e: unknown) => { pending = undefined; throw e; });
  return pending;
}

export const frenchLexiconLoaded = (): boolean => map !== undefined;

/** How many times the data has been parsed in this process (a test hook: it must stay at 1). */
export const frenchLexiconParseCount = (): number => parseCount;

/** Number of distinct normalized lemma keys; 0 before the load. */
export const frenchLexiconSize = (): number => map?.size ?? 0;

/** Calls `cb` once when the load completes (at once when it already has) so the adapter can drop what it cached. */
export function onFrenchLexiconLoaded(cb: () => void): void {
  if (map) cb(); else waiting.push(cb);
}

const maskOf = (lemma: string): number => map?.get(normalizeFr(lemma)) ?? 0;

/** Is this lemma (compared by normalizeFr) listed with this part of speech (any listed part of speech when `pos` is omitted)? False before the load. */
export function fullLemma(lemma: string, pos?: PartOfSpeech): boolean {
  const mask = maskOf(lemma);
  if (!mask) return false;
  if (pos === undefined) return (mask & 63) !== 0;
  const b = POS_BIT[pos];
  return b !== undefined && (mask & (1 << b)) !== 0;
}

/** The gender the list gives a noun: 'Masc', 'Fem' or 'Fem,Masc' (both); undefined when the lemma is not a noun there or no gender is stated. */
export function fullGender(lemma: string): 'Masc' | 'Fem' | 'Fem,Masc' | undefined {
  return GENDER_NAME[(maskOf(lemma) >> GENDER_SHIFT) & 3];
}

/** The flags of this lemma with this part of speech; undefined when it is not listed with it. Only the flags that are set are present. */
export function fullFlags(lemma: string, pos: PartOfSpeech): { pronominal?: boolean; dated?: boolean; hAspire?: boolean } | undefined {
  const mask = maskOf(lemma);
  const b = POS_BIT[pos];
  if (b === undefined || !(mask & (1 << b))) return undefined;
  const out: { pronominal?: boolean; dated?: boolean; hAspire?: boolean } = {};
  if (pos === 'VERB' && mask & (1 << PRON_BIT)) out.pronominal = true;
  if (mask & (1 << (DATED_SHIFT + b))) out.dated = true;
  if (mask & (1 << (H_SHIFT + b))) out.hAspire = true;
  return out;
}

/** Every part of speech this lemma is listed with (empty when none, and before the load). */
export function fullPosOf(lemma: string): PartOfSpeech[] {
  const mask = maskOf(lemma);
  const out: PartOfSpeech[] = [];
  for (let p = 0; p < POS_LIST.length; p++) if (mask & (1 << p)) out.push(POS_LIST[p] as PartOfSpeech);
  return out;
}
